**Program.cs** — stdio transport with DI:

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: route all logging to stderr so stdout stays clean for JSON-RPC
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("api", client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

**ApiTools.cs** — tool class wrapping a REST API:

```csharp
using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        return await client.GetStringAsync($"/posts/{id}", cancellationToken);
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter to posts by this user ID")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        return await client.GetStringAsync(url, cancellationToken);
    }

    [McpServerTool(Destructive = false, ReadOnly = true),
     Description("Search posts by title keyword.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search in post titles")] string keyword,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var json = await client.GetStringAsync("/posts", cancellationToken);
        var posts = JsonSerializer.Deserialize<JsonElement>(json);

        var matches = posts.EnumerateArray()
            .Where(p => p.GetProperty("title").GetString()!
                .Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        return JsonSerializer.Serialize(matches);
    }
}
```

---

### How DI works for MCP tools

The SDK uses two injection styles:

| Style | How it works |
|-------|-------------|
| **Constructor injection** (shown above) | Make the tool class **non-static** with a primary constructor. Services like `IHttpClientFactory`, `ILogger<T>` are injected at construction. The SDK creates one instance per tool call. |
| **Method parameter injection** | Make the class **static**. DI services appear as method parameters alongside user-facing params. The SDK auto-resolves them. |

**Key rule:** The SDK distinguishes user parameters from injected ones by type. `CancellationToken`, `IMcpServer`, `IProgress<T>`, and any DI-registered service are **never** exposed in the tool's JSON schema — only `[Description]`-annotated parameters appear to the LLM.

To scaffold this project:
```bash
dotnet new mcpserver -n MyApiServer
```
Then replace the generated files with the code above, or start from `dotnet new console` and `dotnet add package ModelContextProtocol`.
